package com.bonsaimarket.backend.workflow;

import com.bonsaimarket.backend.auth.AuthPrincipal;
import com.bonsaimarket.backend.user.*;
import com.bonsaimarket.backend.store.*;
import com.bonsaimarket.backend.order.*;
import com.bonsaimarket.backend.order.Order;
import com.bonsaimarket.backend.refund.RefundService;
import com.bonsaimarket.backend.marketplace.MarketplaceException;
import com.bonsaimarket.backend.support.BaselineSql;
import java.math.BigDecimal;
import java.time.LocalDateTime;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.webmvc.test.autoconfigure.AutoConfigureMockMvc;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.authentication.UsernamePasswordAuthenticationToken;
import org.springframework.security.core.authority.SimpleGrantedAuthority;
import org.springframework.test.web.servlet.MockMvc;
import org.springframework.test.web.servlet.request.RequestPostProcessor;
import static org.junit.jupiter.api.Assertions.*;
import static org.springframework.security.test.web.servlet.request.SecurityMockMvcRequestPostProcessors.*;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;

@SpringBootTest(properties={"spring.profiles.active=workflow-test","spring.datasource.url=jdbc:h2:mem:workflow;MODE=MySQL;DB_CLOSE_DELAY=-1;LOCK_TIMEOUT=10000","spring.datasource.driver-class-name=org.h2.Driver","spring.datasource.username=sa","spring.datasource.password=","spring.flyway.enabled=false","spring.jpa.hibernate.ddl-auto=none","orders.mail.enabled=false","ai.enabled=false","vnpay.enabled=false"})
@AutoConfigureMockMvc @TestInstance(TestInstance.Lifecycle.PER_CLASS)
class FeatureWorkflowIntegrationTest {
    @Autowired JdbcTemplate db; @Autowired MockMvc mvc; @Autowired RefundService refunds;
    @Autowired com.bonsaimarket.backend.messaging.PrivateMessaging messaging;
    @Autowired org.springframework.transaction.PlatformTransactionManager transactionManager;
    @Autowired UserRepository users; @Autowired StoreRepository stores; @Autowired OrderRepository orders;
    User buyer,seller,admin,other;Store store;Order order;
    java.sql.Connection bootstrap;
    @BeforeAll void schema()throws Exception{bootstrap=db.getDataSource().getConnection();BaselineSql.schema(bootstrap);}
    @AfterAll void close()throws Exception{bootstrap.close();}
    @BeforeEach void fixture(){
        buyer=user(UserRole.CUSTOMER);seller=user(UserRole.SELLER);admin=user(UserRole.ADMIN);other=user(UserRole.CUSTOMER);
        store=new Store();store.setOwner(seller);store.setName("Gian hàng riêng "+UUID.randomUUID());store.setStatus(StoreStatus.ACTIVE);store.setCreatedAt(LocalDateTime.now());store.setUpdatedAt(LocalDateTime.now());store=stores.save(store);
        order=new Order();order.setCode(UUID.randomUUID().toString());order.setStore(store);order.setBuyer(buyer);order.setStatus(OrderStatus.PENDING);order.setSubtotal(new BigDecimal("100000"));order.setShippingFee(BigDecimal.ZERO);order.setTotal(order.getSubtotal());order.setShippingMethod("STANDARD");order.setShippingAddressSnapshot("Isolated fixture");order.setCreatedAt(LocalDateTime.now());order.setUpdatedAt(order.getCreatedAt());order=orders.save(order);
    }
    User user(UserRole role){var u=new User();u.setName(role+" fixture");u.setEmail(UUID.randomUUID()+"@example.invalid");u.setRole(role);u.setIsActive(true);u.setPasswordHash("!disabled!");u.setEmailVerifiedAt(LocalDateTime.now());u.setCreatedAt(LocalDateTime.now());u.setUpdatedAt(LocalDateTime.now());return users.save(u);}
    RequestPostProcessor as(User u){return authentication(UsernamePasswordAuthenticationToken.authenticated(AuthPrincipal.of(u),null,List.of(new SimpleGrantedAuthority("ROLE_"+u.getRole()))));}
    void paid(String amount){db.update("insert into transactions(order_id,transaction_code,payment_method,amount,status,created_at,updated_at) values(?,?,'VNPAY',?,'SUCCESS',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)",order.getId(),UUID.randomUUID().toString(),new BigDecimal(amount));}
    RefundService.Overview request(){return refunds.request(buyer.getId(),order.getId(),"account",new RefundService.Write("Yêu cầu xem xét giao dịch đã trả"));}
    void code(String expected,Runnable action){assertEquals(expected,assertThrows(MarketplaceException.class,action::run).code);}
    @Test void refundIsServerDerivedAndDuplicateRequestIsIdempotent(){paid("100000");var r=request();assertEquals(new BigDecimal("100000.00"),r.refund().amount());assertEquals(r.refund().id(),request().refund().id());assertEquals(1,r.refund().history().size());assertEquals("REQUESTED",r.refund().status());assertEquals(OrderStatus.PENDING,orders.findById(order.getId()).orElseThrow().getStatus());}
    @Test void refundRejectsUnpaidMismatchAndMultiplePayments(){code("REFUND_NO_PAYMENT_EVIDENCE",this::request);paid("99999");code("REFUND_AMOUNT_MISMATCH",this::request);paid("100000");code("REFUND_RECONCILIATION_REQUIRED",this::request);}
    @Test void refundPermissionsAndFinancialSuccessAreClosed(){paid("100000");var r=request().refund();code("FORBIDDEN",()->refunds.decide(buyer.getId(),r.id(),new RefundService.Decision("APPROVED","forged approval",0L)));code("REFUND_STATE_INVALID",()->refunds.decide(admin.getId(),r.id(),new RefundService.Decision("SUCCEEDED","HTTP 200 is not financial proof",0L)));code("REFUND_EXISTS",()->refunds.request(buyer.getId(),order.getId(),"account",new RefundService.Write("Another request")));}
    @Test void refundLifecycleRevisionAuditAndNotifications(){paid("100000");var r=request().refund();for(String state:List.of("APPROVED","PROCESSING","AWAITING_EXTERNAL","UNKNOWN"))r=refunds.decide(admin.getId(),r.id(),new RefundService.Decision(state,"Đối soát xử lý nội bộ",r.revision()));assertEquals(5,r.history().size());long id=r.id(),revision=r.revision();code("DATA_CONFLICT",()->refunds.decide(admin.getId(),id,new RefundService.Decision("FAILED","Stale",0L)));code("REFUND_STATE_INVALID",()->refunds.decide(admin.getId(),id,new RefundService.Decision("PROCESSING","No blind retry",revision)));assertEquals(5,db.queryForObject("select count(*) from marketplace_audit where target_type='REFUND' and target_id=?",Integer.class,id));assertEquals(5,db.queryForObject("select count(*) from order_notification_outbox where order_id=? and recipient=?",Integer.class,order.getId(),buyer.getEmail()));}
    @Test void refundDenialRequiresReasonAndPreservesHistory(){paid("100000");var r=request().refund();code("VALIDATION_FAILED",()->refunds.decide(admin.getId(),r.id(),new RefundService.Decision("DENIED"," ",0L)));assertEquals("DENIED",refunds.decide(admin.getId(),r.id(),new RefundService.Decision("DENIED","Đã đối chiếu: không đủ điều kiện",0L)).status());}
    @Test void refundGuestCsrfIdorAndSellerCannotDecide()throws Exception{
        paid("100000");long id=request().refund().id();String path="/api/account/orders/"+order.getId()+"/refund";
        mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).with(as(other))).andExpect(status().isNotFound());mvc.perform(get("/api/seller/orders/"+order.getId()+"/refund").with(as(user(UserRole.SELLER)))).andExpect(status().isNotFound());
        mvc.perform(post(path).with(as(buyer)).contentType("application/json").content("{\"reason\":\"test\"}")).andExpect(status().isForbidden());
        mvc.perform(post("/api/admin/refunds/"+id+"/status").with(as(seller)).with(csrf()).contentType("application/json").content("{\"status\":\"APPROVED\",\"reason\":\"test\",\"revision\":0}")).andExpect(status().isForbidden());
    }
    @Test void concurrentRefundRequestsCreateOneRecord()throws Exception{paid("100000");try(var pool=Executors.newFixedThreadPool(2)){var calls=pool.invokeAll(List.of(()->request().refund().id(),()->request().refund().id()));assertEquals(calls.get(0).get(),calls.get(1).get());}assertEquals(1,db.queryForObject("select count(*) from order_refunds where order_id=?",Integer.class,order.getId()));}
    @Test void refundDatabaseRejectsSuccessWithoutEvidence(){paid("100000");long id=request().refund().id();assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("update order_refunds set status='SUCCEEDED' where id=?",id));assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("update order_refunds set amount=-1 where id=?",id));}
    @Test void refundOutboxHistoryAndAuditRollBackTogether(){paid("100000");var tx=new org.springframework.transaction.support.TransactionTemplate(transactionManager);tx.setIsolationLevel(org.springframework.transaction.TransactionDefinition.ISOLATION_READ_COMMITTED);assertThrows(IllegalStateException.class,()->tx.execute(s->{request();throw new IllegalStateException("rollback fixture");}));assertEquals(0,db.queryForObject("select count(*) from order_refunds where order_id=?",Integer.class,order.getId()));assertEquals(0,db.queryForObject("select count(*) from order_notification_outbox where order_id=?",Integer.class,order.getId()));}
    @Test void refundAfterHandoffRequiresReturnAndNeverBypassesCancellationGuard(){paid("100000");order.setStatus(OrderStatus.SHIPPING);orders.save(order);code("REFUND_RETURN_REQUIRED",this::request);order.setStatus(OrderStatus.CANCELLED);orders.save(order);assertEquals("REQUESTED",request().refund().status());assertEquals(OrderStatus.CANCELLED,orders.findById(order.getId()).orElseThrow().getStatus());}
    @Test void refundFailureRetainsPaymentEvidenceAndRequiresReconciliationBeforeRetry(){paid("100000");var r=request().refund();r=refunds.decide(admin.getId(),r.id(),new RefundService.Decision("APPROVED","Review fixture",r.revision()));r=refunds.decide(admin.getId(),r.id(),new RefundService.Decision("PROCESSING","External workflow fixture",r.revision()));r=refunds.decide(admin.getId(),r.id(),new RefundService.Decision("FAILED","External processing failed; no financial success",r.revision()));long id=r.id(),revision=r.revision();code("REFUND_STATE_INVALID",()->refunds.decide(admin.getId(),id,new RefundService.Decision("PROCESSING","Blind retry blocked",revision)));assertEquals("SUCCESS",db.queryForObject("select status from transactions where order_id=?",String.class,order.getId()));assertEquals(4,r.history().size());}
    long conversation(){return messaging.start(buyer.getId(),new com.bonsaimarket.backend.messaging.PrivateMessaging.Start(store.getId(),null)).id();}
    com.bonsaimarket.backend.messaging.PrivateMessaging.Send message(String text){return new com.bonsaimarket.backend.messaging.PrivateMessaging.Send(text,UUID.randomUUID().toString());}
    @Test void buyerSellerConversationIsDurableUniqueAndPrivate(){long id=conversation();assertEquals(id,conversation());assertEquals(1,messaging.list(buyer.getId(),0).totalElements());assertEquals(1,messaging.list(seller.getId(),0).totalElements());assertEquals(0,messaging.list(admin.getId(),0).totalElements());messaging.send(buyer.getId(),id,message("Chào gian hàng"));assertEquals("Chào gian hàng",messaging.messages(seller.getId(),id,null,null).content().getFirst().body());code("NOT_FOUND",()->messaging.detail(other.getId(),id));code("NOT_FOUND",()->messaging.detail(admin.getId(),id));}
    @Test void adminSupportIsParticipantScopedForBothRoles(){for(var peer:List.of(buyer,seller)){var c=messaging.start(admin.getId(),new com.bonsaimarket.backend.messaging.PrivateMessaging.Start(null,peer.getId()));messaging.send(peer.getId(),c.id(),message("Trả lời hỗ trợ"));assertEquals(1,messaging.messages(admin.getId(),c.id(),null,null).content().size());code("NOT_FOUND",()->messaging.detail(user(UserRole.ADMIN).getId(),c.id()));assertEquals(c.id(),messaging.start(admin.getId(),new com.bonsaimarket.backend.messaging.PrivateMessaging.Start(null,peer.getId())).id());}code("FORBIDDEN",()->messaging.start(buyer.getId(),new com.bonsaimarket.backend.messaging.PrivateMessaging.Start(null,seller.getId())));}
    @Test void messageRetryDeduplicatesAndRejectsReusedKeyForChangedBody(){long id=conversation();var input=message("Gửi một lần");var a=messaging.send(buyer.getId(),id,input);assertEquals(a.sequence(),messaging.send(buyer.getId(),id,input).sequence());code("MESSAGE_KEY_REUSED",()->messaging.send(buyer.getId(),id,new com.bonsaimarket.backend.messaging.PrivateMessaging.Send("Nội dung khác",input.clientKey())));assertEquals(1,messaging.messages(seller.getId(),id,null,null).content().size());}
    @Test void messageReadCursorIsMonotonicAndDoesNotReadFutureMessages(){long id=conversation();messaging.send(buyer.getId(),id,message("Một"));messaging.send(seller.getId(),id,message("Hai"));assertEquals(1,messaging.detail(seller.getId(),id).unreadCount());assertEquals(1,messaging.unread(buyer.getId()));messaging.markRead(seller.getId(),id,new com.bonsaimarket.backend.messaging.PrivateMessaging.Read(2L));messaging.markRead(seller.getId(),id,new com.bonsaimarket.backend.messaging.PrivateMessaging.Read(0L));assertEquals(0,messaging.detail(seller.getId(),id).unreadCount());code("VALIDATION_FAILED",()->messaging.markRead(buyer.getId(),id,new com.bonsaimarket.backend.messaging.PrivateMessaging.Read(999L)));}
    @Test void messagePaginationHandlesHistoryAndCatchupWithoutGaps(){long id=conversation();for(int i=1;i<=61;i++)db.update("insert into private_messages(conversation_id,sequence_no,sender_id,client_key,body,created_at) values(?,?,?,?,?,CURRENT_TIMESTAMP)",id,i,buyer.getId(),UUID.randomUUID().toString(),"Tin "+i);db.update("update private_conversations set next_sequence=61 where id=?",id);var recent=messaging.messages(seller.getId(),id,null,null);assertEquals(12,recent.content().getFirst().sequence());assertTrue(recent.hasMore());assertEquals(11,messaging.messages(seller.getId(),id,null,12L).content().size());var first=messaging.messages(seller.getId(),id,0L,null);assertEquals(1,first.content().getFirst().sequence());assertTrue(first.hasMore());assertEquals(11,messaging.messages(seller.getId(),id,50L,null).content().size());}
    @Test void messageValidationAndPlainTextXss(){long id=conversation();for(String text:List.of(" ","a".repeat(4001),"\u0001"))code("VALIDATION_FAILED",()->messaging.send(buyer.getId(),id,message(text)));code("VALIDATION_FAILED",()->messaging.send(buyer.getId(),id,new com.bonsaimarket.backend.messaging.PrivateMessaging.Send("x","short")));String xss="<img src=x onerror=alert(1)>";messaging.send(buyer.getId(),id,message(xss));assertEquals(xss,messaging.messages(seller.getId(),id,null,null).content().getFirst().body());}
    @Test void messageDatabaseEnforcesParticipantAndRetryUniqueness(){long id=conversation();var input=message("Unique");messaging.send(buyer.getId(),id,input);assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("insert into private_messages(conversation_id,sequence_no,sender_id,client_key,body,created_at) values(?,2,?,?,'forged',CURRENT_TIMESTAMP)",id,other.getId(),UUID.randomUUID().toString()));assertThrows(org.springframework.dao.DataIntegrityViolationException.class,()->db.update("insert into private_messages(conversation_id,sequence_no,sender_id,client_key,body,created_at) values(?,2,?,?,'duplicate',CURRENT_TIMESTAMP)",id,buyer.getId(),input.clientKey()));}
    @Test void concurrentCreationAndMessagesStayOrderedAndDeduplicated()throws Exception{try(var pool=Executors.newFixedThreadPool(2)){var created=pool.invokeAll(List.<Callable<Long>>of(this::conversation,this::conversation));long id=created.getFirst().get();assertEquals(id,created.getLast().get());var input=message("Retry đồng thời");var sent=pool.invokeAll(List.<Callable<Long>>of(()->messaging.send(buyer.getId(),id,input).sequence(),()->messaging.send(buyer.getId(),id,input).sequence()));assertEquals(sent.getFirst().get(),sent.getLast().get());var two=pool.invokeAll(List.<Callable<Long>>of(()->messaging.send(buyer.getId(),id,message("Buyer")).sequence(),()->messaging.send(seller.getId(),id,message("Seller")).sequence()));assertNotEquals(two.getFirst().get(),two.getLast().get());assertEquals(List.of(1L,2L,3L),messaging.messages(buyer.getId(),id,null,null).content().stream().map(com.bonsaimarket.backend.messaging.PrivateMessaging.Message::sequence).toList());}}
    @Test void messageHttpSecurityCsrfForgedSenderAndAccountSwitching()throws Exception{long id=conversation();String path="/api/account/conversations/"+id; mvc.perform(get(path)).andExpect(status().isUnauthorized());mvc.perform(get(path).with(as(other))).andExpect(status().isNotFound());mvc.perform(get(path).with(as(admin))).andExpect(status().isNotFound());mvc.perform(post(path+"/messages").with(as(buyer)).contentType("application/json").content("{}")).andExpect(status().isForbidden());mvc.perform(post(path+"/messages").with(as(buyer)).with(csrf()).contentType("application/json").content("{\"body\":\"Forged sender ignored\",\"clientKey\":\"abcdefghijklmnop\",\"senderId\":"+other.getId()+",\"role\":\"ADMIN\"}")).andExpect(status().isOk()).andExpect(jsonPath("$.senderId").value(buyer.getId()));mvc.perform(get(path+"/messages").with(as(seller))).andExpect(jsonPath("$.content[0].body").value("Forged sender ignored"));mvc.perform(get(path+"/messages").with(as(other))).andExpect(status().isNotFound());}
    @Test void messageRateLimitAlsoCountsOtherConversations(){long id=conversation();for(int i=0;i<30;i++)messaging.send(buyer.getId(),id,message("Tin "+i));code("MESSAGE_RATE_LIMIT",()->messaging.send(buyer.getId(),id,message("Rate limit")));assertEquals(30,messaging.messages(seller.getId(),id,null,null).content().size());}
}
